using System.IO;using System.Runtime.CompilerServices;using System.Numerics;
namespace DanceStudio;
// Preview-only name mapping. Source HKX bindings and exporter validation stay intact.
public sealed class SkeletonPreviewPlan {
 public bool Compatible;public bool Strict;public string Warning="";readonly string language=UiText.Language;public int[] Map=[];int[]? mirrorMap;Quaternion[]? mirrorCorrection;
 static readonly ConditionalWeakTable<MotionClip,ConditionalWeakTable<Rig,SkeletonPreviewPlan>> cache=new();
 public static SkeletonPreviewPlan For(MotionClip c,Rig r){var plans=cache.GetValue(c,_=>new());var p=plans.GetValue(r,rig=>Create(c,rig));if(p.language!=UiText.Language){plans.Remove(r);p=plans.GetValue(r,rig=>Create(c,rig));}return p;}
 static SkeletonPreviewPlan Create(MotionClip c,Rig r){if(c.Container!=null&&Convert.ToInt32(c.Container.bindings[c.BindingIndex].blendHint)!=0)return new(){Warning=UiText.T("t0043")};try{c.ValidateRig(r);return new(){Compatible=true,Strict=true,Map=c.BoneMap,Warning=c.Container!=null&&r.SkeletonOnly&&c.Container.skeletons?.Any(s=>s.name==c.Container.bindings[c.BindingIndex].originalSkeletonName)!=true?UiText.T("skeletonExternalContract"):""};}catch(Exception e) when(e is InvalidDataException or HkxMappingRequired or NotSupportedException){var source=c.Container?.skeletons?.FirstOrDefault(s=>s.name==c.Container.bindings[c.BindingIndex].originalSkeletonName);if(source!=null&&c.BoneMap.Any(i=>i>=source.bones.Count))return new(){Warning=UiText.T("t0045")};string[] names=[];if(source!=null&&c.BoneMap.All(i=>i<source.bones.Count))names=c.BoneMap.Select(i=>source.bones[i].name).ToArray();else if(c.Container!=null&&c.Animation.annotationTracks.Count==c.Tracks){names=c.Animation.annotationTracks.Select(t=>t.trackName).ToArray();if(names.Any(string.IsNullOrWhiteSpace)||names.Distinct(StringComparer.Ordinal).Count()!=names.Length)names=[];}if(names.Length!=c.Tracks)return new(){Warning=UiText.T("skeletonMappingBlocked")+"\n"+e.Message};var lookup=r.Names.Select((n,i)=>(n,i)).ToDictionary(x=>x.n,x=>x.i,StringComparer.Ordinal);var map=names.Select(n=>lookup.GetValueOrDefault(n,-1)).ToArray();if(map.All(x=>x<0))return new(){Warning=UiText.T("skeletonMappingBlocked")};return new(){Compatible=true,Map=map,Warning=UiText.F("skeletonMapped",map.Count(i=>i>=0),c.Tracks)};}}
 public Pose[] World(MotionClip c,Rig r,double time,bool mirror,double yaw){if(!Compatible)return r.World(r.Reference);if(Strict)return c.EditedWorld(r,time,mirror,yaw);var local=r.Reference.ToArray();var sampled=c.At(time);for(int i=0;i<Map.Length;i++)if(Map[i]>=0)local[Map[i]]=sampled[i];var world=r.World(local);if(mirror){if(mirrorMap==null){var names=r.Names.Select((n,i)=>(n,i)).ToDictionary(x=>x.n,x=>x.i,StringComparer.Ordinal);mirrorMap=r.Names.Select((n,i)=>names.GetValueOrDefault(PoseEdits.Counterpart(n),i)).ToArray();var reference=r.World(r.Reference);mirrorCorrection=reference.Select((p,i)=>Quaternion.Normalize(Quaternion.Inverse(PoseEdits.Reflect(reference[mirrorMap[i]].R))*p.R)).ToArray();}var original=world.ToArray();for(int i=0;i<world.Length;i++){var p=original[mirrorMap[i]];world[i]=new(PoseEdits.Reflect(p.T),Quaternion.Normalize(PoseEdits.Reflect(p.R)*mirrorCorrection![i]),p.S);}}if(yaw!=0){var q=PoseEdits.Yaw(yaw);for(int i=0;i<world.Length;i++)world[i]=world[i] with{T=Vector3.Transform(world[i].T,q),R=Quaternion.Normalize(q*world[i].R)};}return world;}
}
